```js
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
const W = canvas.width, H = canvas.height;

// state
let state = 'ready'; // ready, playing, levelclear, gameover, win?
let score = 0, lives = 3, level = 1;
let combo = 0;

const paddle = { w: 110, h: 14, x: W/2 - 55, y: H - 40, speed: 520 };
const ball = { x:0, y:0, r:8, dx:0, dy:0, speed:320, stuck:true };

let blocks = [];
function buildLevel(level) {
  blocks = [];
  const rows = Math.min(4 + level, 8);
  const cols = 10;
  const padding = 8;
  const top = 60;
  const bw = (W - padding*(cols+1)) / cols;
  const bh = 24;
  const colors = ['#e74c3c','#e67e22','#f1c40f','#2ecc71','#3498db','#9b59b6'];
  for (let r=0;r<rows;r++){
    for (let c=0;c<cols;c++){
      let hp = 1;
      if (level >= 2 && r < 2 && (r+c)%3===0) hp = 2;
      if (level >= 3 && r === 0) hp = 3;
      blocks.push({x: padding + c*(bw+padding), y: top + r*(bh+padding), w:bw, h:bh, color: colors[r%colors.length], hp, maxhp:hp});
    }
  }
}
```

Ball speed increases per level: speed = 300 + level*30.

Collision: move the ball, check walls, paddle, blocks.

For block collision, find the block that overlaps the ball (circle-rect), determine penetration depth to decide the reflection axis.

Simple approach:
```js
function ballBlockCollision(){
  for (const b of blocks){
    if (b.hp<=0) continue;
    // closest point
    const cx = Math.max(b.x, Math.min(ball.x, b.x+b.w));
    const cy = Math.max(b.y, Math.min(ball.y, b.y+b.h));
    const ddx = ball.x-cx, ddy = ball.y-cy;
    if (ddx*ddx+ddy*ddy <= ball.r*ball.r){
      b.hp--;
      combo++;
      score += 10*combo... 
      // reflect
      // if ball center is outside horizontally vs vertically
      const overlapX = (b.w/2 + ball.r) - Math.abs(ball.x - (b.x+b.w/2));
      const overlapY = (b.h/2 + ball.r) - Math.abs(ball.y - (b.y+b.h/2));
      if (overlapX < overlapY) ball.dx = -ball.dx; else ball.dy = -ball.dy;
      if (b.hp<=0) { /* destroyed */ }
      break; // one block per frame
    }
  }
}
```

HP>0 blocks: color darkens based on hp.

Paddle collision:
```js
if (ball.dy>0 && ball.y+ball.r >= paddle.y && ball.y - ball.r <= paddle.y+paddle.h && ball.x >= paddle.x - ball.r && ball.x <= paddle.x+paddle.w+ball.r){
  const rel = (ball.x - (paddle.x+paddle.w/2)) / (paddle.w/2); // -1..1
  const angle = rel * (Math.PI/3); // max 60deg
  const speed = Math.hypot(ball.dx, ball.dy);
  ball.dx = speed*Math.sin(angle);
  ball.dy = -speed*Math.cos(angle);
  ball.y = paddle.y - ball.r;
  combo = 0; // reset combo when hitting paddle? Common.
}
```

